    #[test]
    fn residual_payload_compacts_the_complete_previous_expression_layout() {
        let saved = size_of::<ResolvedType>() - size_of::<Box<ResolvedType>>();
        assert_eq!(
            size_of::<before::ResolvedExprKind>() - size_of::<ResolvedExprKind>(),
            saved
